/**
 * Domain service that groups contacts by the domain part of their email address.
 * Runs in user mode (with sharing) so only records visible to the running user
 * are returned.
 */
public with sharing class ContactDomainService {

    /**
     * Returns the contacts of the given accounts grouped by the lower-cased
     * domain part of their email address (e.g. 'example.com').
     *
     * - Contacts without an email (or an email without a domain) are excluded.
     * - Each returned Contact has Id, Email and AccountId populated.
     * - A null or empty input set returns an empty map.
     * - Bulk-safe: performs a single SOQL query.
     *
     * @param accountIds the account Ids whose contacts should be grouped
     * @return map of lower-cased email domain to list of contacts
     */
    public static Map<String, List<Contact>> groupByEmailDomain(Set<Id> accountIds) {
        Map<String, List<Contact>> contactsByDomain = new Map<String, List<Contact>>();

        // Guard clause: null or empty input returns an empty map, no query.
        if (accountIds == null || accountIds.isEmpty()) {
            return contactsByDomain;
        }

        // Single bulkified query. Respect the running user's sharing via
        // 'with sharing' on the class; filter out records without an email
        // so we never pull more rows than needed.
        List<Contact> contacts = [
            SELECT Id, Email, AccountId
            FROM Contact
            WHERE AccountId IN :accountIds
              AND Email != null
              AND Email != ''
        ];

        for (Contact contact : contacts) {
            String email = contact.Email;
            if (String.isBlank(email)) {
                continue;
            }

            String domain = email.substringAfter('@').toLowerCase().trim();
            if (String.isBlank(domain)) {
                continue;
            }

            if (!contactsByDomain.containsKey(domain)) {
                contactsByDomain.put(domain, new List<Contact>());
            }
            contactsByDomain.get(domain).add(contact);
        }

        return contactsByDomain;
    }
}
