/**
 * RecordSearchService
 *
 * Dynamic record search service for an admin "record finder" Lightning component.
 *
 * Security model:
 *  - The dynamic SOQL is executed with AccessLevel.USER_MODE, which enforces the
 *    running user's record sharing (row-level access) and field-level security.
 *  - Object/field readability is additionally verified up front via Schema describe
 *    results so that missing access surfaces as a SearchException instead of a
 *    raw QueryException.
 *  - Object and field API names are whitelisted against Schema describe metadata
 *    (never interpolated from raw user input), and filter values are passed as
 *    bind variables via Database.queryWithBinds, making the query safe against
 *    SOQL injection.
 *
 * All validation failures are thrown as RecordSearchService.SearchException.
 */
public with sharing class RecordSearchService {

    /** The only exception type thrown by this service. */
    public class SearchException extends Exception {}

    private static final Integer MAX_ROWS_MIN = 1;
    private static final Integer MAX_ROWS_MAX = 200;

    /**
     * Searches any object with simple equality filters.
     *
     * @param objectApiName API name of the object to query (case-insensitive).
     * @param fields        List of field API names to SELECT in addition to Id (case-insensitive).
     * @param filters       Map of field API name -> equality value; combined with AND.
     *                      May be null or empty (no WHERE clause). Values may be String,
     *                      Boolean, Date, Datetime, Decimal, Integer, Id or null.
     * @param orderByField  Field API name to ORDER BY ascending; ignored when blank.
     * @param maxRows       LIMIT applied to the query; must be between 1 and 200.
     * @return Records matching the criteria, respecting sharing and FLS.
     * @throws SearchException for any invalid input, missing access, or query failure.
     */
    public static List<SObject> search(String objectApiName, List<String> fields, Map<String, Object> filters, String orderByField, Integer maxRows) {
        validateMaxRows(maxRows);

        if (fields == null || fields.isEmpty()) {
            throw new SearchException('fields must not be null or empty.');
        }

        // Resolve and validate the object (throws SearchException if it does not exist).
        Schema.DescribeSObjectResult objectDescribe = describeObject(objectApiName);
        if (!objectDescribe.isAccessible()) {
            throw new SearchException('The running user cannot read object: ' + objectApiName);
        }

        // Case-insensitive lookup of valid, canonical field names for this object.
        Map<String, Schema.SObjectField> fieldMap = buildFieldMap(objectDescribe);

        List<String> selectFields = resolveSelectFields(fields, fieldMap);

        List<String> whereClauses = new List<String>();
        Map<String, Object> binds = resolveFilters(filters, fieldMap, whereClauses);

        String orderByClause = resolveOrderBy(orderByField, fieldMap);

        String query = 'SELECT ' + String.join(selectFields, ', ')
                     + ' FROM ' + objectDescribe.getName();
        if (!whereClauses.isEmpty()) {
            query += ' WHERE ' + String.join(whereClauses, ' AND ');
        }
        if (orderByClause != null) {
            query += orderByClause;
        }
        query += ' LIMIT ' + maxRows;

        try {
            // USER_MODE enforces the running user's sharing rules and field-level security.
            // Filter values are bound (not concatenated), preventing SOQL injection.
            return Database.queryWithBinds(query, binds, AccessLevel.USER_MODE);
        } catch (Exception e) {
            throw new SearchException('Search query failed: ' + e.getMessage());
        }
    }

    /** Validates that maxRows is a non-null Integer within 1..200. */
    private static void validateMaxRows(Integer maxRows) {
        if (maxRows == null || maxRows < MAX_ROWS_MIN || maxRows > MAX_ROWS_MAX) {
            throw new SearchException('maxRows must be a whole number between ' + MAX_ROWS_MIN + ' and ' + MAX_ROWS_MAX + '.');
        }
    }

    /**
     * Resolves the requested object type. Schema.describeSObjects is case-insensitive
     * and cheaper than Schema.getGlobalDescribe(); any failure is surfaced as a
     * SearchException indicating the object does not exist.
     */
    private static Schema.DescribeSObjectResult describeObject(String objectApiName) {
        if (String.isBlank(objectApiName)) {
            throw new SearchException('Object does not exist: ' + objectApiName);
        }
        try {
            List<Schema.DescribeSObjectResult> results = Schema.describeSObjects(new List<String>{ objectApiName });
            return results[0];
        } catch (Exception e) {
            throw new SearchException('Object does not exist: ' + objectApiName);
        }
    }

    /** Builds a lowercase-keyed field map so lookups are reliably case-insensitive. */
    private static Map<String, Schema.SObjectField> buildFieldMap(Schema.DescribeSObjectResult objectDescribe) {
        Map<String, Schema.SObjectField> result = new Map<String, Schema.SObjectField>();
        for (Schema.SObjectField field : objectDescribe.fields.getMap().values()) {
            result.put(field.getDescribe().getName().toLowerCase(), field);
        }
        return result;
    }

    /** Resolves a user-supplied field name to its describe result, or throws SearchException. */
    private static Schema.DescribeFieldResult resolveAndDescribe(Map<String, Schema.SObjectField> fieldMap, String fieldName, String context) {
        if (fieldName == null || String.isBlank(fieldName)) {
            throw new SearchException('Field name must not be blank (' + context + ').');
        }
        Schema.SObjectField field = fieldMap.get(fieldName.toLowerCase());
        if (field == null) {
            throw new SearchException('Field is not a valid field of the object (' + context + '): ' + fieldName);
        }
        return field.getDescribe();
    }

    /** Validates the requested SELECT fields and returns the canonical, deduplicated list (Id first). */
    private static List<String> resolveSelectFields(List<String> fields, Map<String, Schema.SObjectField> fieldMap) {
        List<String> selectFields = new List<String>{ 'Id' };
        Set<String> seen = new Set<String>{ 'id' };
        for (String fieldName : fields) {
            Schema.DescribeFieldResult describe = resolveAndDescribe(fieldMap, fieldName, 'selected');
            if (!describe.isAccessible()) {
                throw new SearchException('The running user cannot read field: ' + fieldName);
            }
            String canonicalKey = describe.getName().toLowerCase();
            if (!seen.contains(canonicalKey)) {
                seen.add(canonicalKey);
                selectFields.add(describe.getName());
            }
        }
        return selectFields;
    }

    /**
     * Validates filter keys (existence, readability, filterability), converts each
     * entry into an equality condition, and returns the bind variables for the query.
     * Null values use the SOQL "field = null" form; all other values are bound.
     */
    private static Map<String, Object> resolveFilters(Map<String, Object> filters, Map<String, Schema.SObjectField> fieldMap, List<String> whereClauses) {
        Map<String, Object> binds = new Map<String, Object>();
        if (filters == null || filters.isEmpty()) {
            return binds;
        }
        Integer bindIndex = 0;
        for (String key : filters.keySet()) {
            Schema.DescribeFieldResult describe = resolveAndDescribe(fieldMap, key, 'filter');
            if (!describe.isAccessible()) {
                throw new SearchException('The running user cannot read filter field: ' + key);
            }
            if (!describe.isFilterable()) {
                throw new SearchException('Filter field cannot be filtered: ' + key);
            }
            String canonicalName = describe.getName();
            Object value = filters.get(key);
            if (value == null) {
                whereClauses.add(canonicalName + ' = null');
            } else {
                String bindName = 'filterValue' + bindIndex;
                bindIndex++;
                whereClauses.add(canonicalName + ' = :' + bindName);
                binds.put(bindName, value);
            }
        }
        return binds;
    }

    /** Validates and returns the ORDER BY clause, or null when orderByField is blank. */
    private static String resolveOrderBy(String orderByField, Map<String, Schema.SObjectField> fieldMap) {
        if (String.isBlank(orderByField)) {
            return null;
        }
        Schema.DescribeFieldResult describe = resolveAndDescribe(fieldMap, orderByField, 'order by');
        if (!describe.isAccessible()) {
            throw new SearchException('The running user cannot read order-by field: ' + orderByField);
        }
        if (!describe.isSortable()) {
            throw new SearchException('Order-by field cannot be sorted: ' + orderByField);
        }
        return ' ORDER BY ' + describe.getName() + ' ASC';
    }
}
