/**
 * Parses e-commerce order JSON payloads posted to an Apex REST endpoint
 * and builds acknowledgement responses.
 */
public with sharing class OrderPayloadParser {

    /** Raised for any malformed or invalid order payload. */
    public class PayloadException extends Exception {}

    /** A single order line item. */
    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    /** The parsed order. */
    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    private static final Integer MONEY_SCALE = 2;

    /**
     * Parses the JSON body into an Order.
     * @param body raw request body
     * @return the parsed Order
     * @throws OrderPayloadParser.PayloadException if the body is null/blank,
     *         not valid JSON, not a JSON object, or contains invalid required data
     */
    public static Order parse(String body) {
        if (String.isBlank(body)) {
            throw new PayloadException('Request body is null or blank.');
        }

        Object root;
        try {
            root = JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new PayloadException('Request body is not valid JSON: ' + e.getMessage());
        }

        if (!(root instanceof Map<String, Object>)) {
            throw new PayloadException('Request body is not a JSON object.');
        }
        Map<String, Object> payload = (Map<String, Object>) root;

        Order order = new Order();

        // --- number: required, non-blank string ---
        Object numberObj = payload.get('number');
        if (!(numberObj instanceof String) || String.isBlank((String) numberObj)) {
            throw new PayloadException('Order "number" is missing or blank.');
        }
        order.orderNumber = (String) numberObj;

        // --- date: optional, ISO yyyy-MM-dd ---
        Object dateObj = payload.get('date');
        if (dateObj instanceof String) {
            try {
                order.orderDate = Date.valueOf((String) dateObj);
            } catch (Exception e) {
                order.orderDate = null;
            }
        }

        // --- currency: optional ---
        Object currencyObj = payload.get('currency');
        if (currencyObj instanceof String) {
            order.currencyCode = (String) currencyObj;
        }

        // --- customer: optional ---
        Object customerObj = payload.get('customer');
        if (customerObj instanceof Map<String, Object>) {
            Object emailObj = ((Map<String, Object>) customerObj).get('email');
            if (emailObj instanceof String) {
                order.customerEmail = (String) emailObj;
            }
        }

        // --- lines: optional; empty list when missing or null ---
        order.lines = new List<Line>();
        Object linesObj = payload.get('lines');
        if (linesObj instanceof List<Object>) {
            for (Object lineObj : (List<Object>) linesObj) {
                if (!(lineObj instanceof Map<String, Object>)) {
                    throw new PayloadException('Order line is not a JSON object.');
                }
                order.lines.add(parseLine((Map<String, Object>) lineObj));
            }
        }

        // --- total: sum of line totals, 0 when there are no lines ---
        Decimal total = 0;
        for (Line line : order.lines) {
            total += line.lineTotal;
        }
        order.total = total.setScale(MONEY_SCALE, RoundingMode.HALF_UP);

        return order;
    }

    private static Line parseLine(Map<String, Object> lineMap) {
        Line line = new Line();

        // --- sku: required, non-blank ---
        Object skuObj = lineMap.get('sku');
        if (!(skuObj instanceof String) || String.isBlank((String) skuObj)) {
            throw new PayloadException('Order line "sku" is missing.');
        }
        line.sku = (String) skuObj;

        // --- quantity: required, positive ---
        Object quantityObj = lineMap.get('quantity');
        if (quantityObj == null) {
            throw new PayloadException('Order line "quantity" is missing for sku ' + line.sku + '.');
        }
        if (quantityObj instanceof Integer) {
            line.quantity = (Integer) quantityObj;
        } else if (quantityObj instanceof Decimal) {
            line.quantity = ((Decimal) quantityObj).intValue();
        } else {
            throw new PayloadException('Order line "quantity" is not a number for sku ' + line.sku + '.');
        }
        if (line.quantity == null || line.quantity <= 0) {
            throw new PayloadException('Order line "quantity" must be positive for sku ' + line.sku + '.');
        }

        // --- unitPrice: required, non-negative ---
        Object unitPriceObj = lineMap.get('unitPrice');
        if (unitPriceObj == null) {
            throw new PayloadException('Order line "unitPrice" is missing for sku ' + line.sku + '.');
        }
        if (unitPriceObj instanceof Decimal) {
            line.unitPrice = (Decimal) unitPriceObj;
        } else if (unitPriceObj instanceof Integer) {
            line.unitPrice = Decimal.valueOf((Integer) unitPriceObj);
        } else {
            throw new PayloadException('Order line "unitPrice" is not a number for sku ' + line.sku + '.');
        }
        if (line.unitPrice < 0) {
            throw new PayloadException('Order line "unitPrice" must not be negative for sku ' + line.sku + '.');
        }

        // --- discount: optional fraction, defaults to 0 ---
        Object discountObj = lineMap.get('discount');
        if (discountObj == null) {
            line.discount = 0;
        } else if (discountObj instanceof Decimal) {
            line.discount = (Decimal) discountObj;
        } else if (discountObj instanceof Integer) {
            line.discount = Decimal.valueOf((Integer) discountObj);
        } else {
            line.discount = 0;
        }

        // --- lineTotal: quantity x unitPrice x (1 - discount), 2 dp, half up ---
        Decimal lineTotal = line.quantity * line.unitPrice * (1 - line.discount);
        line.lineTotal = lineTotal.setScale(MONEY_SCALE, RoundingMode.HALF_UP);

        return line;
    }

    /**
     * Builds the acknowledgement JSON for a parsed order.
     * @param order the parsed order
     * @return JSON object with exactly the keys: number, status, lineCount, total
     */
    public static String toAcknowledgement(Order order) {
        Map<String, Object> ack = new Map<String, Object>();
        ack.put('number', order.orderNumber);
        ack.put('status', 'RECEIVED');
        ack.put('lineCount', order.lines == null ? 0 : order.lines.size());
        ack.put('total', order.total);
        return JSON.serialize(ack);
    }
}
