/**
 * Service used by the trade-show lead import screen.
 *
 * Inserts every lead that can be inserted using a single DML statement
 * (Database.insert with allOrNone=false, so individual failures do not
 * roll back the whole batch and the method never throws for per-record
 * validation failures).
 */
public with sharing class LeadImportService {

    public class ImportResult {
        // number of leads inserted
        public Integer successCount;
        // Ids of the inserted leads, in input order
        public List<Id> insertedIds;
        // input position (0-based) -> error message
        public Map<Integer, String> errorsByIndex;

        public ImportResult() {
            this.successCount = 0;
            this.insertedIds = new List<Id>();
            this.errorsByIndex = new Map<Integer, String>();
        }
    }

    private static final String DEFAULT_LEAD_SOURCE = 'Web';

    /**
     * Inserts the given leads, skipping in-batch duplicates by email
     * (case-insensitive, trimmed) and defaulting a blank LeadSource to 'Web'.
     * Uses exactly one DML statement per call.
     *
     * @param leads the leads to import, may be null or empty
     * @return an ImportResult whose members are never null
     */
    public static LeadImportService.ImportResult importLeads(List<Lead> leads) {
        ImportResult result = new ImportResult();

        if (leads == null || leads.isEmpty()) {
            return result;
        }

        List<Lead> toInsert = new List<Lead>();
        // position in toInsert -> original input index
        Map<Integer, Integer> inputIndexByBatchPosition = new Map<Integer, Integer>();
        Set<String> seenEmails = new Set<String>();

        for (Integer i = 0; i < leads.size(); i++) {
            Lead source = leads[i];

            if (source == null) {
                result.errorsByIndex.put(i, 'Invalid lead: record is null');
                continue;
            }

            // Work on a copy so the caller's records are not mutated.
            Lead lead = source.clone(false);

            String email = lead.Email;
            if (String.isNotBlank(email)) {
                String normalizedEmail = email.trim().toLowerCase();
                if (seenEmails.contains(normalizedEmail)) {
                    result.errorsByIndex.put(
                        i,
                        'Duplicate email in import: ' + normalizedEmail
                    );
                    // Not sent to the database; first occurrence wins even
                    // if it later fails to insert.
                    continue;
                }
                seenEmails.add(normalizedEmail);
            }

            if (String.isBlank(lead.LeadSource)) {
                lead.LeadSource = DEFAULT_LEAD_SOURCE;
            }

            inputIndexByBatchPosition.put(toInsert.size(), i);
            toInsert.add(lead);
        }

        if (toInsert.isEmpty()) {
            return result;
        }

        // Single DML statement; allOrNone=false allows partial success and
        // returns a SaveResult per record instead of throwing on failures.
        List<Database.SaveResult> saveResults = Database.insert(toInsert, false);

        for (Integer j = 0; j < saveResults.size(); j++) {
            Database.SaveResult saveResult = saveResults[j];
            Integer inputIndex = inputIndexByBatchPosition.get(j);

            if (saveResult.isSuccess()) {
                result.insertedIds.add(saveResult.getId());
                result.successCount++;
            } else {
                List<String> messages = new List<String>();
                for (Database.Error err : saveResult.getErrors()) {
                    messages.add(err.getMessage());
                }
                result.errorsByIndex.put(inputIndex, String.join(messages, '; '));
            }
        }

        return result;
    }
}
