/**
 * Queueable job that marks Accounts as synced to the ERP.
 *
 * - The first run is enqueued with attempt = 1.
 * - On every run, an ErpSyncFinalizer is attached as the transaction finalizer
 *   BEFORE any work is performed, so that every run is logged (success or failure)
 *   and failed runs are retried (up to 3 attempts total).
 * - The update is all-or-nothing: if any Account cannot be saved, the exception
 *   is NOT caught, so the job fails and none of its changes are committed.
 */
public with sharing class ErpAccountSyncJob implements Queueable {

    private final Set<Id> accountIds;
    private final Integer attempt;

    /**
     * @param accountIds the Accounts to mark as synced
     * @param attempt    the attempt number (1 for the first run)
     */
    public ErpAccountSyncJob(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds == null ? new Set<Id>() : accountIds;
        this.attempt = attempt == null ? 1 : attempt;
    }

    public void execute(QueueableContext context) {
        // Attach the finalizer before doing any work, so that this run is
        // logged and retried even if the work below throws.
        System.attachFinalizer(new ErpSyncFinalizer(accountIds, attempt));

        List<Account> accountsToUpdate = new List<Account>();
        for (Id accountId : accountIds) {
            accountsToUpdate.add(new Account(
                Id = accountId,
                Description = 'Synced to ERP'
            ));
        }

        // All-or-nothing save. Any error throws an uncaught DmlException,
        // which fails the job and rolls back every change in this transaction.
        update accountsToUpdate;
    }
}
