/**
 * Transaction finalizer for ErpAccountSyncJob.
 *
 * Inserts one FB_Job_Log__c per run:
 * - 'Success' when the parent job succeeded;
 * - 'Failed' (with the truncated exception message) when it failed.
 *
 * On a failed run with attempt < 3, enqueues a new ErpAccountSyncJob for the
 * same accounts with the attempt incremented by 1. After the third failed
 * attempt, nothing more is enqueued.
 */
public with sharing class ErpSyncFinalizer implements Finalizer {

    private static final String JOB_NAME = 'ErpAccountSyncJob';
    private static final Integer MAX_ATTEMPTS = 3;
    private static final Integer ERROR_FIELD_LENGTH = 255;

    private final Set<Id> accountIds;
    private final Integer attempt;

    /**
     * @param accountIds the Accounts the parent job was processing
     * @param attempt    the parent job's attempt number
     */
    public ErpSyncFinalizer(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds == null ? new Set<Id>() : accountIds;
        this.attempt = attempt == null ? 1 : attempt;
    }

    public void execute(FinalizerContext context) {
        Boolean success = context.getResult() == ParentJobResult.SUCCESS;

        FB_Job_Log__c logRecord = new FB_Job_Log__c(
            Job_Name__c = JOB_NAME,
            Status__c = success ? 'Success' : 'Failed',
            Attempt__c = attempt
        );

        if (!success) {
            String errorMessage = '';
            Exception error = context.getException();
            if (error != null) {
                errorMessage = error.getMessage();
            }
            if (errorMessage.length() > ERROR_FIELD_LENGTH) {
                errorMessage = errorMessage.substring(0, ERROR_FIELD_LENGTH);
            }
            logRecord.Error__c = errorMessage;
        }

        insert logRecord;

        // Retry failed runs until the attempt limit is reached.
        if (!success && attempt < MAX_ATTEMPTS) {
            System.enqueueJob(new ErpAccountSyncJob(accountIds, attempt + 1));
        }
    }
}
