/**
 * Keeps Account.FB_Open_Pipeline__c (sum of Amount of open Opportunities) and
 * Account.FB_Open_Opportunities__c (count of open Opportunities) up to date.
 *
 * Design notes:
 * - Recalculation is always performed by aggregating from the database (not from
 *   Trigger.new), so the totals are correct after *every* DML statement in a
 *   transaction, even when the same records are modified several times
 *   (e.g. a Flow followed by Apex, or multiple statements in a test method).
 * - Only accounts actually affected by the current DML statement are recalculated,
 *   keeping bulk loads of 200+ rows well inside governor limits (one aggregate
 *   query + one Account query + one Account DML per statement).
 * - Account DML is skipped when the computed values already match what is stored.
 *   This makes the interaction with the legacy AccountTrigger safe: when this
 *   handler updates an Account, AccountTrigger re-updates the open Opportunities
 *   (rating copy), which re-fires this trigger, but no relevant field changed, so
 *   no further Account DML occurs and the loop terminates (no unbounded recursion).
 * - Accounts left with no open Opportunities are set to 0 and 0 (never blank).
 */
public inherited sharing class OpportunityPipelineHandler {

    @TestVisible
    private static final String PIPELINE_FIELD = 'FB_Open_Pipeline__c';
    @TestVisible
    private static final String COUNT_FIELD = 'FB_Open_Opportunities__c';

    /**
     * Called for after insert / after undelete: every affected account is recalculated.
     */
    public static void recalculateAccounts(List<Opportunity> opportunities) {
        process(collectAccountIds(opportunities));
    }

    /**
     * Called for after update. Only recalculates when a field that can influence the
     * totals changed: AccountId (the opportunity moved, so both old and new account
     * are affected), Amount, or IsClosed (open <-> closed transitions, which also
     * covers stage changes between open and closed stages).
     */
    public static void recalculateAccounts(List<Opportunity> newOpps, Map<Id, Opportunity> oldMap) {
        if (newOpps == null || newOpps.isEmpty() || oldMap == null) {
            return;
        }
        Set<Id> accountIds = new Set<Id>();
        for (Opportunity newOpp : newOpps) {
            Opportunity oldOpp = oldMap.get(newOpp.Id);
            if (oldOpp == null) {
                accountIds.add(newOpp.AccountId);
                continue;
            }
            Boolean relevantChange = newOpp.AccountId != oldOpp.AccountId
                || newOpp.Amount != oldOpp.Amount
                || newOpp.IsClosed != oldOpp.IsClosed;
            if (relevantChange) {
                accountIds.add(newOpp.AccountId);
                accountIds.add(oldOpp.AccountId);
            }
        }
        process(accountIds);
    }

    /**
     * Called for after delete: every account that lost an opportunity is recalculated.
     */
    public static void recalculateAccountsForDelete(List<Opportunity> oldOpps) {
        process(collectAccountIds(oldOpps));
    }

    private static Set<Id> collectAccountIds(List<Opportunity> opportunities) {
        Set<Id> accountIds = new Set<Id>();
        if (opportunities != null) {
            for (Opportunity opp : opportunities) {
                if (opp.AccountId != null) {
                    accountIds.add(opp.AccountId);
                }
            }
        }
        return accountIds;
    }

    private static void process(Set<Id> accountIds) {
        accountIds.remove(null);
        if (accountIds.isEmpty()) {
            return;
        }

        // Aggregate the open pipeline straight from the database so we always see
        // the state as of the current DML statement. SUM() ignores null Amounts
        // (blank counts as 0); accounts with no open rows are absent from the result.
        Map<Id, AggregateResult> resultsById = new Map<Id, AggregateResult>();
        for (AggregateResult ar : [
            SELECT AccountId, SUM(Amount) pipelineTotal, COUNT() oppCount
            FROM Opportunity
            WHERE AccountId IN :accountIds AND IsClosed = false
            GROUP BY AccountId
        ]) {
            resultsById.put((Id) ar.get('AccountId'), ar);
        }

        List<Account> accountsToUpdate = new List<Account>();
        for (Account acc : [
            SELECT Id, FB_Open_Pipeline__c, FB_Open_Opportunities__c
            FROM Account
            WHERE Id IN :accountIds
        ]) {
            AggregateResult ar = resultsById.get(acc.Id);
            Decimal pipeline = (ar == null || ar.get('pipelineTotal') == null)
                ? 0
                : (Decimal) ar.get('pipelineTotal');
            Integer openCount = (ar == null) ? 0 : (Integer) ar.get('oppCount');

            // Write only when something actually changed. In particular, an account
            // whose last open opportunity went away is explicitly set to 0 / 0
            // (instead of being left blank or skipped).
            if (acc.FB_Open_Pipeline__c != pipeline || acc.FB_Open_Opportunities__c != openCount) {
                acc.FB_Open_Pipeline__c = pipeline;
                acc.FB_Open_Opportunities__c = openCount;
                accountsToUpdate.add(acc);
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            // This DML may re-fire AccountTrigger (which copies Rating onto open
            // opportunities) and therefore this trigger again. That second pass
            // changes no total-relevant field, so it terminates without further
            // account DML (no recursion guard needed, and no stale static state).
            update accountsToUpdate;
        }
    }
}
