public inherited sharing class LogPurgeJob implements Schedulable {

    private static final String JOB_NAME = 'Log purge (nightly)';
    private static final Integer INFO_RETENTION_DAYS = 30;
    private static final Integer ERROR_RETENTION_DAYS = 180;

    public LogPurgeJob() {
        // No-argument constructor required for schedulable jobs.
    }

    public void execute(SchedulableContext ctx) {
        purgeOldLogs();
    }

    /**
     * Deletes FB_Integration_Log__c records older than 30 days, except
     * ERROR logs which are kept until they are older than 180 days.
     */
    public static void purgeOldLogs() {
        // Records that must be deleted:
        // - everything older than 30 days, EXCEPT ERROR logs (so Level__c != 'ERROR')
        List<FB_Integration_Log__c> standardOldLogs = [
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE CreatedDate < :DateTime.now().addDays(-INFO_RETENTION_DAYS)
              AND (Level__c != 'ERROR' OR Level__c = null)
        ];

        // ERROR logs that are older than 180 days.
        List<FB_Integration_Log__c> veryOldErrorLogs = [
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE CreatedDate < :DateTime.now().addDays(-ERROR_RETENTION_DAYS)
              AND Level__c = 'ERROR'
        ];

        List<FB_Integration_Log__c> toDelete = new List<FB_Integration_Log__c>();
        toDelete.addAll(standardOldLogs);
        toDelete.addAll(veryOldErrorLogs);

        if (!toDelete.isEmpty()) {
            // allOrNone = false so one failed row does not block the purge.
            Database.delete(toDelete, false);
        }
    }

    /**
     * Schedules this job to run every day at 02:00.
     * @return the CronTrigger Id returned by System.schedule.
     */
    public static Id scheduleNightly() {
        return System.schedule(JOB_NAME, '0 0 2 * * ?', new LogPurgeJob());
    }
}
