/**
 * @description Service providing per-account rollups of won-opportunity revenue.
 * All sums are computed in the database via a single aggregate SOQL query;
 * individual Opportunity records are never loaded into memory.
 * The class respects the running user's sharing rules.
 */
public inherited sharing class OpportunityRollupService {

    /**
     * @description Returns each requested account's total closed-won Amount for
     *              the current calendar year.
     * @param accountIds The set of Account Ids to roll up. May be null or empty.
     * @return A map with exactly one entry per requested (non-null) Account Id.
     *         Accounts with no qualifying opportunities — or whose qualifying
     *         opportunities all have a blank Amount — map to 0, never null.
     *         Ids not requested are never keys. A null/empty input set yields
     *         an empty map.
     */
    public static Map<Id, Decimal> wonAmountThisYear(Set<Id> accountIds) {
        Map<Id, Decimal> result = new Map<Id, Decimal>();

        // Rule: a null or empty set returns an empty map.
        if (accountIds == null || accountIds.isEmpty()) {
            return result;
        }

        // Seed every requested Id with 0 so accounts without qualifying
        // opportunities still appear in the result with a value of 0.
        // (Also guard against a stray null Id in the set.)
        for (Id accountId : accountIds) {
            if (accountId != null) {
                result.put(accountId, 0);
            }
        }

        if (result.isEmpty()) {
            return result;
        }

        Integer currentYear = Date.today().year();

        // Single aggregate query: SUM with GROUP BY, executed in the database.
        // SUM(Amount) ignores blank Amounts, so opportunities with a blank
        // Amount contribute nothing; if all Amounts are blank the aggregate
        // itself is null, which we normalize to 0 below.
        for (AggregateResult ar : [
            SELECT AccountId, SUM(Amount) wonTotal
            FROM Opportunity
            WHERE AccountId IN :result.keySet()
              AND IsWon = true
              AND CALENDAR_YEAR(CloseDate) = :currentYear
            GROUP BY AccountId
        ]) {
            Id accountId = (Id) ar.get('AccountId');
            Decimal wonTotal = (Decimal) ar.get('wonTotal');
            result.put(accountId, wonTotal == null ? 0 : wonTotal);
        }

        return result;
    }
}
