public inherited sharing class DealEventPublisher {

    /**
     * Publishes one Deal_Stage_Change__e platform event per Opportunity and
     * returns the publish results in the same order as the input list.
     *
     * Note: deviates from a per-record EventBus.publish loop intentionally.
     * Each EventBus.publish call consumes a DML statement against the
     * 150-statement governor limit, so publishing up to 200 records
     * individually inside a trigger handler would throw a LimitException.
     * The list overload of EventBus.publish is bulkified and returns its
     * SaveResults in the same order as the events passed in, so failures
     * can still be traced to individual opportunities by index.
     *
     * @param opportunities the opportunities to publish stage-change events for
     * @return SaveResults aligned index-for-index with the input list
     */
    public static List<Database.SaveResult> publishStageChanges(List<Opportunity> opportunities) {
        if (opportunities == null || opportunities.isEmpty()) {
            return new List<Database.SaveResult>();
        }

        List<Deal_Stage_Change__e> events = new List<Deal_Stage_Change__e>(opportunities.size());
        for (Opportunity opp : opportunities) {
            events.add(
                new Deal_Stage_Change__e(
                    Opportunity_Id__c = opp.Id,
                    Stage__c = opp.StageName,
                    Amount__c = opp.Amount
                )
            );
        }

        // Single bulk publish: SaveResults are returned in the same order
        // as the events list, hence the same order as the input list.
        return EventBus.publish(events);
    }
}
