/**
 * Recalculates the Rating of each affected Account from its open pipeline.
 * Runs asynchronously (single @future call per transaction) so opportunity saves stay fast.
 */
trigger OpportunityTrigger on Opportunity (after insert, after update) {

    // Only run after DML is committed; ratings are derived data.
    if (Trigger.isAfter) {

        Set<Id> accountIds = new Set<Id>();

        for (Opportunity opp : Trigger.new) {

            if (Trigger.isInsert) {
                if (opp.AccountId != null) {
                    accountIds.add(opp.AccountId);
                }
            } else { // Trigger.isUpdate
                Opportunity oldOpp = Trigger.oldMap.get(opp.Id);
                Boolean stageChanged = opp.StageName != oldOpp.StageName;
                Boolean amountChanged = opp.Amount != oldOpp.Amount;
                Boolean accountChanged = opp.AccountId != oldOpp.AccountId;

                if (stageChanged || amountChanged || accountChanged) {
                    if (opp.AccountId != null) {
                        accountIds.add(opp.AccountId);
                    }
                    // If the opp moved to a different account, the old account's
                    // rating must be recalculated too, otherwise it goes stale.
                    if (accountChanged && oldOpp.AccountId != null) {
                        accountIds.add(oldOpp.AccountId);
                    }
                }
            }
        }

        if (!accountIds.isEmpty()) {
            // One @future call per transaction (200-opportunity batches would
            // otherwise exceed the 50-future-calls-per-transaction limit).
            AccountRatingService.recalculate(accountIds);
        }
    }
}
```

