```javascript
import { LightningElement } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

const DEBOUNCE_DELAY_MS = 300;
const MIN_SEARCH_LENGTH = 2;

export default class ContactSearch extends LightningElement {
    searchTerm = '';
    contacts = [];
    error = null;
    isSearching = false;

    /**
     * Monotonically increasing counter used to discard out-of-order responses.
     * Only the response that matches the latest request id is applied.
     */
    requestSequence = 0;

    /** Timer handle for the debounce. */
    debounceTimeout;

    /** Tracks whether the component is still connected to the DOM. */
    connected = false;

    connectedCallback() {
        this.connected = true;
    }

    disconnectedCallback() {
        this.connected = false;
        this.clearPendingSearch();
    }

    handleSearchChange(event) {
        this.searchTerm = event.target.value;

        // Any new keystroke invalidates a pending debounced search.
        this.clearPendingSearch();

        const trimmed = this.searchTerm.trim();

        if (trimmed.length < MIN_SEARCH_LENGTH) {
            this.contacts = [];
            this.error = null;
            return;
        }

        const requestId = ++this.requestSequence;

        // eslint-disable-next-line @lwc/lwc/no-async-operation
        this.debounceTimeout = setTimeout(() => {
            this.debounceTimeout = undefined;
            this.executeSearch(trimmed, requestId);
        }, DEBOUNCE_DELAY_MS);
    }

    async executeSearch(trimmedTerm, requestId) {
        if (!this.connected) {
            return;
        }

        this.isSearching = true;

        try {
            const results = await searchContacts({ searchTerm: trimmedTerm });

            // Ignore stale responses: only the most recent request may update results.
            if (!this.connected || requestId !== this.requestSequence) {
                return;
            }

            this.contacts = results ?? [];
            this.error = null;
        } catch (error) {
            if (!this.connected || requestId !== this.requestSequence) {
                return;
            }
            this.contacts = [];
            this.error = error;
        } finally {
            if (this.connected && requestId === this.requestSequence) {
                this.isSearching = false;
            }
        }
    }

    clearPendingSearch() {
        if (this.debounceTimeout) {
            clearTimeout(this.debounceTimeout);
            this.debounceTimeout = undefined;
        }
    }

    get hasResults() {
        return !this.error && Array.isArray(this.contacts) && this.contacts.length > 0;
    }

    get showNoResults() {
        return (
            !this.error &&
            !this.isSearching &&
            Array.isArray(this.contacts) &&
            this.contacts.length === 0 &&
            this.searchTerm.trim().length >= MIN_SEARCH_LENGTH
        );
    }
}
