import { api, LightningElement, track } from 'lwc';
import Favorite_Add from '@salesforce/label/c.Favorite_Add';
import Favorite_Remove from '@salesforce/label/c.Favorite_Remove';

/**
 * Icon-style toggle button that marks a record as a favorite.
 *
 * The `favorite` public property is owned by the parent. The component keeps
 * a private tracked copy so that:
 *  - the parent can push new values at any time (e.g. after a server refresh);
 *  - clicks can flip the displayed state optimistically without reassigning
 *    an @api property (which would violate @lwc/lwc/no-api-reassignments).
 */
export default class FavoriteToggle extends LightningElement {
    @track _favorite = false;

    @api
    get favorite() {
        return this._favorite;
    }

    set favorite(value) {
        this._favorite = !!value;
    }

    /**
     * Native aria-pressed must be the strings "true"/"false".
     */
    get ariaPressed() {
        return this._favorite ? 'true' : 'false';
    }

    /**
     * The accessible name is the action a click performs:
     * clicking removes when already a favorite, adds when not.
     */
    get actionLabel() {
        return this._favorite ? Favorite_Remove : Favorite_Add;
    }

    get iconStyle() {
        return this._favorite
            ? 'fill: rgb(228, 172, 0); stroke: rgb(228, 172, 0); stroke-width: 1.5;'
            : 'fill: none; stroke: currentcolor; stroke-width: 1.5;';
    }

    /**
     * Optimistic UI: flip the displayed state immediately, then notify the
     * parent with the new value. The parent may later confirm or revert by
     * updating the `favorite` public property.
     */
    handleClick() {
        this._favorite = !this._favorite;
        this.dispatchEvent(
            new CustomEvent('favoritechange', {
                detail: { favorite: this._favorite },
            }),
        );
    }
}
