import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

const REFRESH_INTERVAL_MS = 60000;

export default class QueueMonitor extends LightningElement {
    waiting;
    longestWaitMinutes;
    error;

    inFlight = false;
    pollIntervalId;

    // Arrow function so `this` is bound and the same reference can be removed later.
    handleVisibilityChange = () => {
        if (document.visibilityState === 'visible') {
            // Page became visible again: refresh immediately.
            // The interval keeps running; the next tick fires in 60s.
            this.load();
        }
    };

    connectedCallback() {
        this.load();
        this.pollIntervalId = setInterval(() => this.load(), REFRESH_INTERVAL_MS);
        document.addEventListener('visibilitychange', this.handleVisibilityChange);
    }

    disconnectedCallback() {
        if (this.pollIntervalId) {
            clearInterval(this.pollIntervalId);
            this.pollIntervalId = undefined;
        }
        document.removeEventListener('visibilitychange', this.handleVisibilityChange);
    }

    async load() {
        // Skip if a request is already in flight, or the tab is hidden in the background.
        if (this.inFlight || document.visibilityState === 'hidden') {
            return;
        }
        this.inFlight = true;
        try {
            const stats = await getQueueStats();
            this.waiting = stats.waiting;
            this.longestWaitMinutes = stats.longestWaitMinutes;
            // Clear any previous error after a successful refresh.
            this.error = undefined;
        } catch (e) {
            // Show the error but keep polling; it will be cleared on next success.
            this.error = e;
        } finally {
            this.inFlight = false;
        }
    }

    get hasStats() {
        return this.waiting !== undefined && this.waiting !== null;
    }
}
