        const inputs = [...this.template.querySelectorAll('lightning-input')];

        // Step 1: work-email validation before reporting validity.
        const emailInput = this.template.querySelector('lightning-input[data-field="email"]');
        const emailDomain = (this.email || '').split('@').pop().toLowerCase();
        if (BLOCKED_DOMAINS.includes(emailDomain)) {
