        // Step 2: show messages on all invalid fields at once.
        inputs.forEach((input) => input.reportValidity());

        // Step 3: stop if any input is invalid.
        if (inputs.some((input) => !input.checkValidity())) {
            return;
        }

        try {
            await register({
                fullName: this.fullName,
                email: this.email,
                company: this.company
            });
            // Step 4a: success toast.
            this.dispatchEvent(
                new ShowToastEvent({
                    variant: 'success',
                    title: 'Registered'
                })
            );
        } catch (error) {
            // Step 4b: error toast.
            this.dispatchEvent(
                new ShowToastEvent({
                    variant: 'error',
                    title: 'Registration failed',
                    message: error.body.message
                })
            );
        }
    }
