import { LightningElement, api } from 'lwc';

let uidCounter = 0;

export default class StatusListbox extends LightningElement {
    @api label;
    @api options = [];

    _value;
    _activeIndex = 0;
    _uid;

    constructor() {
        super();
        uidCounter += 1;
        this._uid = `status-listbox-${uidCounter}`;
    }

    @api
    get value() {
        return this._value;
    }

    set value(newValue) {
        this._value = newValue;
        const index = this.options.findIndex((option) => option.value === newValue);
        if (index !== -1) {
            // The parent changed the selection: move the active option to it.
            this._activeIndex = index;
        } else if (this.options.length) {
            // Nothing (valid) is selected: fall back to the first option.
            this._activeIndex = 0;
        }
    }

    /**
     * The active index, clamped to the current options range so that a
     * shrunken options array can never leave a dangling active descendant.
     */
    get activeIndex() {
        if (!this.options.length) {
            return 0;
        }
        return Math.min(Math.max(this._activeIndex, 0), this.options.length - 1);
    }

    get renderOptions() {
        return this.options.map((option, index) => ({
            ...option,
            index,
            id: `${this._uid}-option-${index}`,
            ariaSelected: option.value === this._value ? 'true' : 'false',
            classes: index === this.activeIndex
                ? 'status-listbox__option status-listbox__option_active'
                : 'status-listbox__option',
        }));
    }

    get activeId() {
        const items = this.renderOptions;
        return items.length ? items[this.activeIndex].id : undefined;
    }

    handleKeyDown(event) {
        const { key } = event;
        const handledKeys = ['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', ' '];

        // Only intercept the six pattern keys; Tab and everything else keeps
        // its default behaviour.
        if (!handledKeys.includes(key)) {
            return;
        }
        event.preventDefault();

        const length = this.options.length;
        if (!length) {
            return;
        }

        let nextIndex = this.activeIndex;

        switch (key) {
            case 'ArrowDown':
                nextIndex = Math.min(this.activeIndex + 1, length - 1);
                break;
            case 'ArrowUp':
                nextIndex = Math.max(this.activeIndex - 1, 0);
                break;
            case 'Home':
                nextIndex = 0;
                break;
            case 'End':
                nextIndex = length - 1;
                break;
            case 'Enter':
            case ' ':
                this.select(this.activeIndex);
                return;
            default:
                return;
        }

        // Moving the active option never changes the selection.
        this._activeIndex = nextIndex;
    }

    handleClick(event) {
        const index = Number(event.currentTarget.dataset.index);
        this.select(index);
    }

    select(index) {
        if (index < 0 || index >= this.options.length) {
            return;
        }
        // Clicking (or keyboard-selecting) an option also makes it active.
        this._activeIndex = index;

        const option = this.options[index];
        if (option.value !== this._value) {
            this._value = option.value;
            this.dispatchEvent(
                new CustomEvent('change', {
                    detail: { value: option.value },
                })
            );
        }
        // If the option was already selected, nothing is dispatched.
    }
}
