```html
<!-- force-app/main/default/lwc/taskChecklist/taskChecklist.html -->
<template>
    <h2 class="heading">{headingLabel}</h2>
    <ul>
        <template for:each={items} for:item="task">
            <li key={task.id} data-id={task.id}>
                <input
                    type="checkbox"
                    data-id={task.id}
                    checked={task.done}
                    onchange={handleToggle}
                />
                <span>{task.label}</span>
            </li>
        </template>
    </ul>
    <p class="remaining">{remaining} remaining</p>
    <lightning-input
        class="new-task"
        label="New task"
