/**
 * @description Sets each Contact's current employer as the Contact's primary NPSP
 *              affiliation to an existing Organization Account.
 *
 * The method relies on the NPSP Affiliation trigger (the "standard mechanism") to:
 *   - demote the Contact's previous Current/Primary affiliation to Former,
 *     non-Primary, with an End Date of today, and
 *   - keep Contact.npsp__Primary_Affiliation__c pointing at the organization of the
 *     Contact's Current/Primary affiliation.
 *
 * Governor budget (own queries/DML):
 *   - 1 SOQL query (all Current affiliations for the contacts, plus any existing
 *     affiliation with one of the target organizations)
 *   - up to 2 DML statements (one affiliation update, one affiliation insert)
 *
 * Bulk-safe: no SOQL or DML inside loops; handles 200 contacts in a single call.
 */
public inherited sharing class EmployerService {

    private static final String STATUS_CURRENT = 'Current';
    private static final String ROLE_EMPLOYEE = 'Employee';

    /**
     * @param employerByContactId Map of Contact Id -> Organization Account Id.
     *                            Null/empty map (or null keys/values) is a no-op.
     */
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        // Sanitize input: ignore null keys/values.
        Map<Id, Id> targetOrgByContactId = new Map<Id, Id>();
        Set<Id> contactIds = new Set<Id>();
        Set<Id> orgIds = new Set<Id>();
        for (Id contactId : employerByContactId.keySet()) {
            Id orgId = employerByContactId.get(contactId);
            if (contactId != null && orgId != null) {
                targetOrgByContactId.put(contactId, orgId);
                contactIds.add(contactId);
                orgIds.add(orgId);
            }
        }
        if (targetOrgByContactId.isEmpty()) {
            return;
        }

        // SOQL #1: every Current affiliation for these contacts (so NPSP can demote the
        // previous primary employer via its trigger), plus every affiliation (any status)
        // between these contacts and the target organizations (so we never create duplicates).
        List<npe5__Affiliation__c> existingAffiliations = [
            SELECT Id,
                   npe5__Contact__c,
                   npe5__Organization__c,
                   npe5__Status__c,
                   npe5__Primary__c,
                   npe5__StartDate__c
            FROM npe5__Affiliation__c
            WHERE npe5__Contact__c IN :contactIds
              AND (npe5__Status__c = :STATUS_CURRENT
                   OR npe5__Organization__c IN :orgIds)
        ];

        // Existing affiliations between a contact and its target organization, by contact.
        Map<Id, List<npe5__Affiliation__c>> affiliationsWithTargetByContactId =
            new Map<Id, List<npe5__Affiliation__c>>();
        // Contacts whose target organization is already their Current, Primary affiliation.
        Set<Id> alreadyCurrentPrimaryContactIds = new Set<Id>();

        for (npe5__Affiliation__c aff : existingAffiliations) {
            if (orgIds.contains(aff.npe5__Organization__c)) {
                if (!affiliationsWithTargetByContactId.containsKey(aff.npe5__Contact__c)) {
                    affiliationsWithTargetByContactId.put(
                        aff.npe5__Contact__c, new List<npe5__Affiliation__c>());
                }
                affiliationsWithTargetByContactId.get(aff.npe5__Contact__c).add(aff);
            }
            if (aff.npe5__Status__c == STATUS_CURRENT
                    && aff.npe5__Primary__c == true
                    && aff.npe5__Organization__c == targetOrgByContactId.get(aff.npe5__Contact__c)) {
                // Nothing changes for this contact: the organization already is the
                // Current, Primary affiliation (NPSP keeps the Contact lookup in sync).
                alreadyCurrentPrimaryContactIds.add(aff.npe5__Contact__c);
            }
        }

        List<npe5__Affiliation__c> affiliationsToUpdate = new List<npe5__Affiliation__c>();
        List<npe5__Affiliation__c> affiliationsToInsert = new List<npe5__Affiliation__c>();
        Date today = Date.today();

        for (Id contactId : targetOrgByContactId.keySet()) {
            if (alreadyCurrentPrimaryContactIds.contains(contactId)) {
                continue;
            }
            Id orgId = targetOrgByContactId.get(contactId);

            // Prefer an existing Current affiliation with the target org over a Former one,
            // so we reactivate the freshest relationship instead of an old one.
            npe5__Affiliation__c selected = null;
            List<npe5__Affiliation__c> candidates = affiliationsWithTargetByContactId.get(contactId);
            if (candidates != null) {
                for (npe5__Affiliation__c candidate : candidates) {
                    if (selected == null) {
                        selected = candidate;
                    } else if (candidate.npe5__Status__c == STATUS_CURRENT
                               && selected.npe5__Status__c != STATUS_CURRENT) {
                        selected = candidate;
                    }
                }
            }

            if (selected != null) {
                // Reactivate/promote the existing affiliation to Current + Primary.
                // NPSP's trigger will demote the previous Current/Primary affiliation
                // (Former, non-primary, End Date = today) and update
                // Contact.npsp__Primary_Affiliation__c to this organization.
                if (selected.npe5__Status__c != STATUS_CURRENT) {
                    selected.npe5__Status__c = STATUS_CURRENT;
                    selected.npe5__StartDate__c = today;
                }
                selected.npe5__Primary__c = true;
                selected.npe5__EndDate__c = null;
                affiliationsToUpdate.add(selected);
            } else {
                // No existing relationship with this organization: create the
                // Current, Primary affiliation. NPSP's trigger handles the rest.
                affiliationsToInsert.add(new npe5__Affiliation__c(
                    npe5__Contact__c = contactId,
                    npe5__Organization__c = orgId,
                    npe5__Status__c = STATUS_CURRENT,
                    npe5__Primary__c = true,
                    npe5__StartDate__c = today,
                    npe5__Role__c = ROLE_EMPLOYEE
                ));
            }
        }

        // DML #1 and #2 (each executed only when non-empty).
        if (!affiliationsToUpdate.isEmpty()) {
            update affiliationsToUpdate;
        }
        if (!affiliationsToInsert.isEmpty()) {
            insert affiliationsToInsert;
        }
    }
}
