/**
 * @description Converts an open donation (pledge) into a monthly installment plan.
 *
 * Existing paid and written-off payments are treated as history and left untouched.
 * All other (unpaid, not written-off) payments are deleted and replaced by
 * `numberOfPayments` new unpaid payments, scheduled monthly starting on
 * `firstPaymentDate`. The outstanding amount (Opportunity Amount minus the
 * amounts of paid and written-off payments) is distributed evenly, rounded down
 * to the cent, with the last payment absorbing any remainder so the payments
 * add up exactly to the outstanding amount.
 *
 * All validation happens before any DML, so if an exception is thrown the
 * opportunity's payments are left unchanged.
 */
public with sharing class PaymentPlanService {

    public class PaymentPlanException extends Exception {}

    private static final Integer CURRENCY_SCALE = 2;

    /**
     * @param opportunityId     Id of the pledge (Opportunity) to schedule.
     * @param numberOfPayments  Number of installments to create. Must be >= 1.
     * @param firstPaymentDate  Scheduled date of the first installment; each
     *                          subsequent installment is one month later.
     * @return The inserted payments in schedule order.
     * @throws PaymentPlanService.PaymentPlanException if inputs are invalid,
     *         the opportunity does not exist or is closed, or the outstanding
     *         amount is not greater than zero.
     */
    public static List<npe01__OppPayment__c> scheduleInstallments(
        Id opportunityId,
        Integer numberOfPayments,
        Date firstPaymentDate
    ) {
        validateNumberOfPayments(numberOfPayments);

        Opportunity opp = getOpportunity(opportunityId);

        if (opp.IsClosed) {
            throw new PaymentPlanException(
                'Cannot schedule installments: the opportunity is closed.'
            );
        }

        List<npe01__OppPayment__c> existingPayments = [
            SELECT Id,
                   npe01__Payment_Amount__c,
                   npe01__Paid__c,
                   npe01__Written_Off__c
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opportunityId
        ];

        // Paid and written-off payments are history; everything else is replaced.
        List<npe01__OppPayment__c> paymentsToDelete = new List<npe01__OppPayment__c>();
        Decimal settledAmount = 0;
        for (npe01__OppPayment__c payment : existingPayments) {
            if (payment.npe01__Paid__c == true || payment.npe01__Written_Off__c == true) {
                settledAmount += (payment.npe01__Payment_Amount__c == null)
                    ? 0
                    : payment.npe01__Payment_Amount__c;
            } else {
                paymentsToDelete.add(payment);
            }
        }

        Decimal opportunityAmount = (opp.Amount == null) ? 0 : opp.Amount;
        Decimal outstandingAmount = opportunityAmount - settledAmount;

        if (outstandingAmount <= 0) {
            throw new PaymentPlanException(
                'Cannot schedule installments: the outstanding amount must be greater than zero.'
            );
        }

        List<npe01__OppPayment__c> newPayments = buildInstallments(
            opportunityId,
            numberOfPayments,
            firstPaymentDate,
            outstandingAmount
        );

        // All validation has passed; safe to modify data.
        delete paymentsToDelete;

        insert newPayments;

        return newPayments;
    }

    private static void validateNumberOfPayments(Integer numberOfPayments) {
        if (numberOfPayments == null || numberOfPayments < 1) {
            throw new PaymentPlanException(
                'Cannot schedule installments: numberOfPayments must be at least 1.'
            );
        }
    }

    private static Opportunity getOpportunity(Id opportunityId) {
        if (opportunityId == null) {
            throw new PaymentPlanException(
                'Cannot schedule installments: opportunityId is required.'
            );
        }

        List<Opportunity> opportunities = [
            SELECT Id, Amount, IsClosed
            FROM Opportunity
            WHERE Id = :opportunityId
        ];

        if (opportunities.isEmpty()) {
            throw new PaymentPlanException(
                'Cannot schedule installments: no Opportunity found with Id ' + opportunityId + '.'
            );
        }

        return opportunities[0];
    }

    /**
     * Builds the installment payments without performing any DML.
     * Each payment is the outstanding amount divided by the number of payments,
     * rounded DOWN to the cent; the last payment absorbs the remainder so the
     * installments sum exactly to the outstanding amount.
     */
    private static List<npe01__OppPayment__c> buildInstallments(
        Id opportunityId,
        Integer numberOfPayments,
        Date firstPaymentDate,
        Decimal outstandingAmount
    ) {
        Decimal regularAmount = (outstandingAmount / numberOfPayments)
            .setScale(CURRENCY_SCALE, RoundingMode.DOWN);

        Decimal allocatedSoFar = regularAmount * (numberOfPayments - 1);
        Decimal lastAmount = outstandingAmount - allocatedSoFar;

        List<npe01__OppPayment__c> payments = new List<npe01__OppPayment__c>();
        for (Integer i = 0; i < numberOfPayments; i++) {
            Decimal amount = (i == numberOfPayments - 1) ? lastAmount : regularAmount;

            payments.add(new npe01__OppPayment__c(
                npe01__Opportunity__c = opportunityId,
                npe01__Payment_Amount__c = amount,
                npe01__Scheduled_Date__c = firstPaymentDate.addMonths(i),
                npe01__Paid__c = false,
                npe01__Written_Off__c = false
            ));
        }

        return payments;
    }
}
