/**
 * @description FamilyService
 *
 * Imports NPSP family links from an external student system.
 *
 * For each (child -> parent) pair, creates a single NPSP Relationship record:
 *
 *   npe4__Contact__c          = child
 *   npe4__RelatedContact__c   = parent
 *   npe4__Type__c             = 'Parent'
 *   npe4__Status__c           = 'Current'
 *
 * NPSP's Relationship trigger (List Setting reciprocal method) then creates the
 * reciprocal record in its own DML: parent -> child typed Son / Daughter / Child,
 * resolved from the npe4__Relationship_Lookup__c entry named 'Parent' according
 * to the child's gender. This keeps the end state to exactly one relationship
 * record in each direction per pair.
 *
 * Guarantees:
 *  - Null or empty input does nothing (no SOQL, no DML).
 *  - Pairs where a relationship already exists between the two contacts (in
 *    either direction) are skipped, so the import can be re-run safely.
 *  - The same unordered pair appearing twice in the input (A->B and B->A) is
 *    only processed once.
 *  - For 200 pairs this method issues at most 1 SOQL query and 1 DML statement
 *    of its own (a single bulkified insert; NPSP's trigger does the rest).
 */
public inherited sharing class FamilyService {

    /** NPSP Relationship type used on the child -> parent record. */
    private static final String TYPE_PARENT = 'Parent';

    /** NPSP Relationship status required by the import. */
    private static final String STATUS_CURRENT = 'Current';

    /**
     * @description Links each parent to its child in NPSP.
     * @param parentIdByChildId Map of child Contact Id (key) to parent Contact Id (value).
     */
    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        // Null or empty input: nothing to do.
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // Collect every Contact Id referenced by the input, skipping invalid entries.
        Set<Id> allContactIds = new Set<Id>();
        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId == null || parentId == null) {
                continue;
            }
            allContactIds.add(childId);
            allContactIds.add(parentId);
        }
        if (allContactIds.isEmpty()) {
            return;
        }

        // Single SOQL query: fetch every existing relationship between any two
        // contacts mentioned in the input. Relationships are symmetric for our
        // purposes, so index both directions to make lookups O(1) per pair.
        Map<Id, Set<Id>> existingByContact = new Map<Id, Set<Id>>();
        for (npe4__Relationship__c rel : [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE npe4__Contact__c IN :allContactIds
              AND npe4__RelatedContact__c IN :allContactIds
        ]) {
            addAdjacent(existingByContact, rel.npe4__Contact__c, rel.npe4__RelatedContact__c);
            addAdjacent(existingByContact, rel.npe4__RelatedContact__c, rel.npe4__Contact__c);
        }

        List<npe4__Relationship__c> relationshipsToInsert = new List<npe4__Relationship__c>();
        Set<String> processedPairs = new Set<String>();

        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);

            // Ignore incomplete entries and self-relationships.
            if (childId == null || parentId == null || childId == parentId) {
                continue;
            }

            // Deduplicate unordered pairs so A->B and B->A in the same call
            // only produce one relationship (NPSP adds the reciprocal).
            String pairKey = pairKey(childId, parentId);
            if (!processedPairs.add(pairKey)) {
                continue;
            }

            // Skip if any relationship already exists between the two contacts
            // (either direction), making the import idempotent/re-runnable.
            if (relationshipExists(existingByContact, childId, parentId)) {
                continue;
            }

            // child is the Contact: NPSP resolves the reciprocal (parent -> child)
            // to Son/Daughter/Child via the 'Parent' Relationship Lookup entry.
            relationshipsToInsert.add(new npe4__Relationship__c(
                npe4__Contact__c        = childId,
                npe4__RelatedContact__c = parentId,
                npe4__Type__c           = TYPE_PARENT,
                npe4__Status__c         = STATUS_CURRENT
            ));
        }

        // Single bulkified DML statement of our own. NPSP's Relationship trigger
        // creates the reciprocal records in its own DML.
        if (!relationshipsToInsert.isEmpty()) {
            insert relationshipsToInsert;
        }
    }

    /**
     * @description Records that contact `a` has a relationship with contact `b`
     *              (stored in both directions by the caller for symmetric lookup).
     */
    private static void addAdjacent(Map<Id, Set<Id>> mapByContact, Id contactId, Id relatedContactId) {
        if (!mapByContact.containsKey(contactId)) {
            mapByContact.put(contactId, new Set<Id>());
        }
        mapByContact.get(contactId).add(relatedContactId);
    }

    /**
     * @description Returns true if a relationship already exists between the two
     *              contacts in either direction.
     */
    private static Boolean relationshipExists(Map<Id, Set<Id>> mapByContact, Id contactId, Id relatedContactId) {
        return (mapByContact.containsKey(contactId) && mapByContact.get(contactId).contains(relatedContactId))
            || (mapByContact.containsKey(relatedContactId) && mapByContact.get(relatedContactId).contains(contactId));
    }

    /**
     * @description Builds a direction-independent key for a pair of Contact Ids,
     *              used to deduplicate (A->B) and (B->A) entries in one call.
     */
    private static String pairKey(Id idA, Id idB) {
        return (String.valueOf(idA) < String.valueOf(idB))
            ? idA + '-' + idB
            : idB + '-' + idA;
    }
}
