/**
 * @description Service for importing contacts from a legacy system.
 *
 * Inserted contacts run through all normal Contact trigger automation
 * (e.g. the TA_Contact_FormatPhone before-insert action still executes),
 * except TA_Contact_CreateWelcomeTask, which is bypassed for the duration
 * of the import because legacy contacts are existing customers.
 *
 * The bypass is scoped to this method only: it is cleared in a finally
 * block so that contacts inserted later in the same transaction receive
 * their welcome tasks as usual, even if the DML throws.
 *
 * Uses the Trigger Actions Framework (Mitch Spano, unlocked package,
 * no namespace) bypass API. Bypassing a single action by name keeps all
 * other Contact actions active, unlike bypassing the whole object via
 * TriggerBase.bypass(Contact.SObjectType).
 */
public inherited sharing class ContactImportService {

    /**
     * @description The API name of the TAF action class registered for
     *              the after-insert Contact trigger handler.
     */
    @TestVisible
    private static final String WELCOME_TASK_ACTION = 'TA_Contact_CreateWelcomeTask';

    /**
     * @description Inserts the given contacts in a single DML statement
     *              with TA_Contact_CreateWelcomeTask skipped. All other
     *              Contact trigger actions still run.
     *
     * @param contacts Contacts to insert. Null entries and records with
     *                 populated Id fields are rejected by the DML layer
     *                 via the standard exception mechanism.
     */
    public static void importContacts(List<Contact> contacts) {
        // Nothing to do; avoid activating (and clearing) a bypass for no reason.
        if (contacts == null || contacts.isEmpty()) {
            return;
        }

        // Remember whether the action was already bypassed before we started,
        // so we never clear a bypass that an earlier caller in this transaction
        // intentionally left in place.
        Boolean wasAlreadyBypassed =
            MetadataTriggerHandler.isBypassed(WELCOME_TASK_ACTION);

        if (!wasAlreadyBypassed) {
            MetadataTriggerHandler.bypass(WELCOME_TASK_ACTION);
        }

        try {
            insert contacts;
        } finally {
            // Always restore state, even on DML failure, so the bypass
            // does not leak into the rest of the transaction.
            if (!wasAlreadyBypassed) {
                MetadataTriggerHandler.clearBypass(WELCOME_TASK_ACTION);
            }
        }
    }
}
