/**
 * @description Trigger Action for the Trigger Actions Framework (Mitch Spano, v0.3.4).
 * Normalizes contact information on every Lead before insert so the values are
 * clean on first save - no extra DML, no SOQL, bulk-safe (200+ records per chunk):
 * - Email:    leading/trailing whitespace removed, lower-cased (null stays null).
 * - Company:  leading/trailing whitespace removed.
 * - LeadSource: set to 'Web' when blank; an existing value is kept.
 * Mutating the records in the before insert context means Salesforce persists the
 * cleaned values in the same DML that created the records.
 */
public inherited sharing class TA_Lead_NormalizeContactInfo implements TriggerAction.BeforeInsert {

    /**
     * @description Cleans Email, Company and LeadSource on all leads in the
     *              triggering batch before they are saved.
     * @param triggerNew The list of Lead records being inserted.
     */
    public void beforeInsert(List<SObject> triggerNew) {
        List<Lead> newLeads = (List<Lead>) triggerNew;

        for (Lead lead : newLeads) {
            // Email: trim and lower-case; a null email stays null.
            if (lead.Email != null) {
                lead.Email = lead.Email.trim().toLowerCase();
            }

            // Company: trim leading/trailing whitespace.
            if (lead.Company != null) {
                lead.Company = lead.Company.trim();
            }

            // LeadSource: default to 'Web' only when blank; keep any existing value.
            if (lead.LeadSource == null) {
                lead.LeadSource = 'Web';
            }
        }
    }
}
