```apex
/**
 * @description After-update Trigger Action (Trigger Actions Framework) that creates a
 * single "Amount changed" Task on each Opportunity whose Amount changed, compared to
 * its pre-trigger values. Inserts are out of scope: this action only runs on update.
 *
 * Recursion safety: the existing TA_Opportunity_RoundAmount action (Order__c 20) re-updates
 * opportunities in the same transaction to round their Amount. That second update re-runs
 * this action. The static `alreadyLogged` set (static state lives for the whole transaction)
 * guarantees at most one "Amount changed" Task per Opportunity per transaction, without
 * modifying the rounding action.
 *
 * Bulk safety: all Task records are collected and inserted with a single DML statement
 * per trigger execution, so 200 opportunities cost exactly one insert.
 */
public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {
    /**
     * @description Opportunity Ids for which a "Amount changed" Task has already been
     * created in the current transaction. Static, therefore transaction-scoped.
     */
    private static Set<Id> alreadyLogged = new Set<Id>();

    /**
     * @description Creates one completed Task per Opportunity whose Amount changed in this
     * trigger invocation, skipping any Opportunity already logged earlier in the transaction.
     * @param triggerNew The new versions of the updated Opportunities.
     * @param triggerOld The old (pre-trigger) versions of the updated Opportunities.
     */
    public void afterUpdate(List<Opportunity> triggerNew, List<Opportunity> triggerOld) {
        Map<Id, Decimal> oldAmountById = new Map<Id, Decimal>();
        for (Opportunity oldOpp : triggerOld) {
            oldAmountById.put(oldOpp.Id, oldOpp.Amount);
        }

        List<Task> tasksToInsert = new List<Task>();
        for (Opportunity opp : triggerNew) {
            if (alreadyLogged.contains(opp.Id)) {
                // Already audited once in this transaction (e.g. after the
                // TA_Opportunity_RoundAmount re-update). Never log twice.
                continue;
            }
            Decimal oldAmount = oldAmountById.get(opp.Id);
            // Apex == is null-safe: null == null is true, null == value is false,
            // so this correctly treats null -> value and value -> null as changes.
            if (opp.Amount == oldAmount) {
                continue;
            }
            alreadyLogged.add(opp.Id);
            tasksToInsert.add(new Task(
                Subject = 'Amount changed',
                WhatId = opp.Id,
                Status = 'Completed'
            ));
        }

        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }
    }
}
